<?php
class Property extends Model{public function all($f=[]){$sql='SELECT properties.*,hosts.company_name,locations.district,locations.city FROM properties JOIN hosts ON properties.host_id=hosts.host_id JOIN locations ON properties.location_id=locations.location_id WHERE 1';$p=[];if(!empty($f['search'])){$sql.=' AND properties.title LIKE ?';$p[]='%'.$f['search'].'%';}if(!empty($f['max_price'])){$sql.=' AND properties.price_per_month<=?';$p[]=$f['max_price'];}if(!empty($f['location_id'])){$sql.=' AND properties.location_id=?';$p[]=$f['location_id'];}$sql.=' ORDER BY property_id DESC';return $this->query($sql,$p)->fetchAll();}public function find($id){return $this->query('SELECT properties.*,hosts.company_name,locations.district,locations.city FROM properties JOIN hosts ON properties.host_id=hosts.host_id JOIN locations ON properties.location_id=locations.location_id WHERE property_id=?',[$id])->fetch();}public function create($d){return $this->query('INSERT INTO properties(host_id,location_id,title,property_type,address,bedrooms,bathrooms,price_per_month,availability_status,image_path,description) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$d['host_id'],$d['location_id'],$d['title'],$d['property_type'],$d['address'],$d['bedrooms'],$d['bathrooms'],$d['price_per_month'],$d['availability_status'],$d['image_path'],$d['description']]);}public function update($id,$d){return $this->query('UPDATE properties SET host_id=?,location_id=?,title=?,property_type=?,address=?,bedrooms=?,bathrooms=?,price_per_month=?,availability_status=?,image_path=?,description=? WHERE property_id=?',[$d['host_id'],$d['location_id'],$d['title'],$d['property_type'],$d['address'],$d['bedrooms'],$d['bathrooms'],$d['price_per_month'],$d['availability_status'],$d['image_path'],$d['description'],$id]);}public function delete($id){return $this->query('DELETE FROM properties WHERE property_id=?',[$id]);}}
